--region import
--endregion import
local KCookie = CS.Engine.Lib.KCookie
--endregion define
local BossRankType = {
	CakeShopBoss = 1,
	ParkMiniWorldBoss = 2,
	ParkMiniWorldBossPartition = 5, ---分榜
}

local RankType = {
	ALL_RANK = 1, --总榜
	PARTITION = 2, --分榜
}
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数

local CommonTabToggleUpEnvPath    = "Game.Behaviours.CommonTabToggleUp"

--- Behavior生命周期：__init -> Awake -> Start -> OnDestroy -> __delete


--- from: Assets/BundleResources/Prefabs/Common/CommonActivityBossMain.prefab > name: ActivityMidFestivalPlayerRankingsDialog
---@class CommonRankRoot
---@field Env                           	CommonRankRoot                          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field EmptyNode                     	UnityEngine.RectTransform               	@ 0    
---@field LayoutListAndMyselef          	UnityEngine.RectTransform               	@ 1    
---@field MyRanking                     	UnityEngine.RectTransform               	@ 2    
---@field LoopView                      	SuperScrollView.LoopListView2           	@ 3    
---@field TileGroup                     	UnityEngine.RectTransform               	@ 4    
---@field TabToggleUpGroup              	UnityEngine.RectTransform               	@ 5    
---@field CommonTabToggleUp             	UnityEngine.RectTransform               	@ 6    
---@field TxtTime                       	UnityEngine.RectTransform               	@ 7    
---@field BtnRank                       	UnityEngine.RectTransform               	@ 8    
---@field BtnTotalRank                  	UnityEngine.RectTransform               	@ 9    
---@field SelectGroup                   	UnityEngine.RectTransform               	@ 10   
---@field AllRankSelectGroup            	UnityEngine.RectTransform               	@ 11   
---@field TxtTimeTotal                  	UnityEngine.RectTransform               	@ 12   
local CommonRankRoot = Class('CommonRankRoot')

--region lifecycle

function CommonRankRoot:__init()
	self.activityContentId = 1
	self.activityUuid = 1
	self.homeData = nil
	self.rankType = -1 ---初始是分榜
	self.rankType = checkNumber(KCookie.Get("CommonRankRoot"))
	if checkNumber(self.rankType) <= 0 then
		self.rankType = RankType.PARTITION
	end
	self.scheduleId = 1
	KCookie.RemoveAllListener("CommonRankRoot")
	self.countdown = nil
end

function CommonRankRoot:__delete()
	self.activityContentId = nil
	self.homeData = nil
end

function CommonRankRoot:Awake()
	CfUtils.SetActive(self.LayoutListAndMyselef, false)
	self:InitHandler()
end

function CommonRankRoot:RemoveTimer()
	---@type Engine.Modules.CDTimerModule
	local cdTimerModule = CDTimerModule.GetInstance()
	if not isNull(self.countdown) then
		cdTimerModule:RemoveCD(self.countdown)
	end
	self.countdown = nil
end

function CommonRankRoot:StartCountDown()
	---@type Engine.Modules.CDTimerModule
	local cdTimerModule = CDTimerModule.GetInstance()
	self:RemoveTimer()
	self.countdown = cdTimerModule:AddCD(1, function(count, id, elapsed)
		if self.homeData then
			if self.rankType == RankType.PARTITION then
				self.homeData.splitRankCloseTime = math.max(checkNumber(self.homeData.splitRankCloseTime) - elapsed, 0)
				if checkNumber(self.homeData.splitRankCloseTime) <= 0 then
					---结束了
					self:RemoveTimer()
				end
				CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS2(checkNumber(self.homeData.splitRankCloseTime)))
			else
				---全局的活动总倒计时
				local closeTime = checkNumber(self.closeTime)
				self.closeTime = math.max(checkNumber(self.closeTime) - elapsed, 0)
				if closeTime <= 0 then
					self:RemoveTimer()
				end
				CfUtils.FillText(self.TxtTimeTotal, CfUtils.GetTimeHMS2(checkNumber(self.closeTime)))
			end
		end
	end, CountDownTime, false, true)
end

function CommonRankRoot:Start()
	self:StartCountDown()
end

function CommonRankRoot:OnDestroy()
	KCookie.Set("CommonRankRoot", checkInt(self.rankType))
	self:RemoveTimer()
	self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function CommonRankRoot:InitHandler()
	---@type ActivityCakeShopBossRankMyCell
	self._myRankScr = CfUtils.GetLuaScr(self.MyRanking, "Game.Behaviours.CommonRankMyCell")
end

---OnRankTypeButtonAction
---点击榜单类型
function CommonRankRoot:OnRankTypeButtonAction(rankType)
	--if self.rankType == rankType then
	--    return
	--end
	self.rankType = rankType
	CfUtils.SetActive(self.TxtTimeTotal, self.rankType == RankType.ALL_RANK)
	CfUtils.SetActive(self.SelectGroup, self.rankType == RankType.PARTITION)
	CfUtils.SetActive(self.AllRankSelectGroup, self.rankType == RankType.ALL_RANK)
	CfUtils.SetActive(self.TabToggleUpGroup, rankType == RankType.PARTITION)
	--先把列表清理下
	GameUtils.ReloadData(self.LoopView, 0)
	if rankType == RankType.PARTITION then
		self:FreshListByListType()
	else
		CfUtils.FillText(self.TxtTimeTotal, CfUtils.GetTimeHMS2(checkNumber(self.closeTime)))
		self.data = self.homeData
		self._rankInfo = self.homeData.rank
		self:RefreshUI()
	end
end

---FreshToggleTab
---刷新顶部的标签信息
function CommonRankRoot:FreshToggleTab(rankType)
	CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS2(checkNumber(self.data.splitRankCloseTime)))
	local toggleData = {}
	local config = checkTable(self.data.splitRankConfig)
	local scheduleId = checkInt(self.homeData.scheduleId)
	self.scheduleId = self.homeData.scheduleId
	
	local rankConfig = table.values(config)
	SortByMember(rankConfig, "order")
	if scheduleId == 0 then
		scheduleId = checkInt(rankConfig[#rankConfig].id)
	end
	local curOrder = config[tostring(scheduleId)].order
	
	for i, v in pairs(rankConfig) do
		local isLock = checkInt(v.order) > curOrder
		table.insert(toggleData,{
			id = checkNumber(v.id),
			order = checkInt(v.order),
			isLock = isLock,
			text = localize('第_num_期', {_num_ = v.order}),
			checkFunc = function()
				if isLock then GameUtils.Toast(localize('当前暂未开启'))  end
				return (not isLock)
			end,
			func = function()
				self.scheduleId = checkInt(v.id)
				GameUtils.ReloadData(self.LoopView, 0)
				self:FreshListByListType()
			end
		})
	end
	self._toggleData = toggleData
	---@type CommonTabToggleUp
	local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, CommonTabToggleUpEnvPath)
	if isNull(env) then return end
	
	if config[tostring(self.scheduleId)] then
		env:FillToggles(self._toggleData,  config[tostring(self.scheduleId)].order)
	else 	
		env:FillToggles(self._toggleData, self.scheduleId)
	end
	--end
end
function CommonRankRoot:FreshListByListType()
	self.entryCtrl:RequestSplitRankList(self.scheduleId, Bind(self,self.RefreshShow))
end

function CommonRankRoot:RefreshShow(response)
	self.data = response.data
	self._rankInfo = self.data.rank
	self:RefreshUI()
end

function CommonRankRoot:InitData()
	self._rankInfo = self.homeData.rank
	SetButtonAction(self.BtnTotalRank, function()
		self:OnRankTypeButtonAction(RankType.ALL_RANK)
	end)
	SetButtonAction(self.BtnRank, function()
		self:OnRankTypeButtonAction(RankType.PARTITION)
	end)
	self:FreshToggleTab(self.rankType)
	self:OnRankTypeButtonAction(self.rankType)
	CfUtils.SetActive(self.TxtTimeTotal, self.rankType == RankType.ALL_RANK)
end
--endregion init

--region handler
--endregion handler

--region public
function CommonRankRoot:Refresh(entryCtrl, activityData)
	self.entryCtrl = entryCtrl
	self.data = self.entryCtrl:GetActivityBossData()
	self.activityUuid = checkInt(activityData.id)
	self.homeData = clone(self.data)
	self.activityContentId = checkNumber(activityData.activityContentId)
	self.closeTime = self:GetCloseTime(activityData)
	self:InitData()
	CfUtils.SetActive(self.controller, true)
end

function CommonRankRoot:GetCloseTime(activityData)
	---@type PlayerComponent
	local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
	if not comp then return 0 end
	local curTime = comp:GetPlayerDojo():GetServerTime()
	curTime = curTime or os.time()
	local seconds = checkInt(activityData.closeTime) - curTime
	if seconds <= 0 then
		return 0, localize("活动已结束")
	end
	return seconds
end
--endregion public

--region private
function CommonRankRoot:OnGetItemByIndex(listView, index)
	local luaIndex = index + 1
	local cellData = self._rankInfo[luaIndex]
	local cell = listView:NewListViewItem("Cell")
	---@type ActivityCakeShopBossRankCell
	local scr = CfUtils.GetLuaScr(cell, "Game.Behaviours.CommonRankRootCell")
	scr:Refresh(cellData, luaIndex, self.entryCtrl,self.rankType)
	return cell
end

function CommonRankRoot:RefreshRankList()
	---@type MidFestivalBossParameterVo
	local parametersVo =  self.entryCtrl:GetBossParametersVo(2)
	local showCount = math.min(checkNumber(parametersVo.num), #self._rankInfo)
	
	if not self.LoopView.IsListViewInit then
		self.LoopView:InitListView(showCount, Bind(self, self.OnGetItemByIndex))
	else
		GameUtils.ReloadData(self.LoopView, showCount)
	end
end

function CommonRankRoot:RefreshMyRank()
	self._myRankScr:Refresh(self.data, self.entryCtrl, self.rankType)
end

function CommonRankRoot:RefreshUI()
	local isEmpty = next(self._rankInfo) == nil
	CfUtils.SetActive(self.LayoutListAndMyselef, not isEmpty)
	CfUtils.SetActive(self.EmptyNode, false)
	if isEmpty then
		CfUtils.SetActive(self.EmptyNode, true)
		return
	end
	
	self:RefreshRankList()
	self:RefreshMyRank()
end
--endregion private

--region get / set
--endregion get / set

return CommonRankRoot

